1	//! The registry-publish role: one adapter per ecosystem, selected once.
2	
3	use callisto_model::{
4	    CommandOutput, Ecosystem, ExactEvidence, ProviderEvidenceV1, ProviderIndeterminateCause, ProviderObservationV1,
5	    PublishOutcome, RegistryError, RegistryKey, Version,
6	};
7	
8	use crate::commands::registry_argv;
9	use crate::error::{CommandFailure, ReleasePreconditionRequirement, RemoteConflict, UnsupportedReleaseFeature};
10	use crate::GraphError;
11	
12	use super::policy::{self, programs, require_registry_confirmation, timeouts, Attempt};
13	use super::{
14	    wrong_role, EffectAuthorization, PreparedOperation, ProviderCapabilities, ProviderContext, ProviderRequest,
15	    RegistryPublishOperation, ReleasePreflight, ReleaseProvider,
16	};
17	
18	pub(crate) struct RegistryProvider;
19	
20	impl ReleaseProvider for RegistryProvider {
21	    fn capabilities(&self) -> ProviderCapabilities {
22	        // Every registry answers an observation. Whether that answer can be
23	        // exact is the adapter's `can_observe_versions`.
24	        ProviderCapabilities {
25	            can_observe: true,
26	            can_publish: true,
27	        }
28	    }
29	
30	    fn observe(
31	        &self,
32	        context: &ProviderContext<'_>,
33	        request: &ProviderRequest<'_>,
34	    ) -> Result<ProviderObservationV1, GraphError> {
35	        let operation = registry_operation(request)?;
36	        registry_observation(adapter_for(request.id.package.ecosystem())?, context, operation)
37	    }
38	
39	    /// A registry index propagates asynchronously, so an absence observed
40	    /// right after a successful publish is lag, not an answer. The receipt
41	    /// pass uses the same bounded retry the post-publish confirmation does:
42	    /// `Absent` is transient, everything else settles as itself, and only a
43	    /// fresh `Exact` can still satisfy the receipt.
44	    fn observe_settled(
45	        &self,
46	        context: &ProviderContext<'_>,
47	        request: &ProviderRequest<'_>,
48	    ) -> Result<ProviderObservationV1, GraphError> {
49	        let operation = registry_operation(request)?;
50	        let adapter = adapter_for(request.id.package.ecosystem())?;
51	        if !adapter.can_observe_versions() {
52	            return self.observe(context, request);
53	        }
54	        confirmed_registry_observation(adapter, context, operation)
55	    }
56	
57	    fn preflight_conflict(&self) -> RemoteConflict {
58	        RemoteConflict::RegistryVersionDiffers
59	    }
60	
61	    fn preflight(
62	        &self,
63	        context: &ProviderContext<'_>,
64	        request: &ProviderRequest<'_>,
65	    ) -> Result<ReleasePreflight, GraphError> {
66	        let operation = registry_operation(request)?;
67	        // A registry version that already exists is a hard conflict, not an
68	        // adopted success: only the recovery path may converge on an exact
69	        // remote observation.
70	        match self.observe(context, request)? {
71	            ProviderObservationV1::Absent => Ok(proceed()),
72	            ProviderObservationV1::Exact { .. } => Err(GraphError::ReleaseRegistryVersionExists {
73	                package: operation.package_name.clone(),
74	                version: operation.version.clone(),
75	            }),
76	            // A registry with no query API at all has nothing to observe
77	            // before the effect; the post-effect confirmation fails closed.
78	            ProviderObservationV1::Indeterminate {
79	                cause: ProviderIndeterminateCause::UnsupportedProvider,
80	            } => Ok(proceed()),
81	            ProviderObservationV1::Indeterminate { .. } => Err(GraphError::ReleaseProviderIndeterminate {
82	                operation: Box::new(request.id.clone()),
83	            }),
84	            ProviderObservationV1::Conflict { .. } => Err(GraphError::ReleaseRemoteConflict {
85	                conflict: self.preflight_conflict(),
86	            }),
87	        }
88	    }
89	
90	    fn publish(
91	        &self,
92	        context: &ProviderContext<'_>,
93	        request: &ProviderRequest<'_>,
94	        _effect: &EffectAuthorization<'_>,
95	    ) -> Result<ExactEvidence, GraphError> {
96	        let operation = registry_operation(request)?;
97	        let adapter = adapter_for(request.id.package.ecosystem())?;
98	        let output = adapter.publish(context, operation)?;
99	        let outcome = adapter.classify(&output).map_err(|source| GraphError::Registry {
100	            package: operation.package_name.clone(),
101	            source,
102	        })?;
103	        // Neither a zero exit nor the client's "already exists" text is a
104	        // receipt: a yanked version is not the version this intent authorized,
105	        // so only an exact observation may satisfy the operation.
106	        let confirmed = if matches!(outcome, PublishOutcome::Published) && adapter.can_observe_versions() {
107	            confirmed_registry_observation(adapter, context, operation)?
108	        } else {
109	            registry_observation(adapter, context, operation)?
110	        };
111	        require_registry_confirmation(
112	            confirmed.is_terminal_success(),
113	            &operation.package_name,
114	            &operation.version,
115	        )?;
116	        confirmed
117	            .exact_evidence()
118	            .ok_or_else(|| GraphError::RegistryPublishUnconfirmed {
119	                package: operation.package_name.clone(),
120	                version: operation.version.clone(),
121	            })
122	    }
123	}
124	
125	fn proceed() -> ReleasePreflight {
126	    ReleasePreflight::Proceed {
127	        proof: ProviderObservationV1::Absent
128	            .absent_proof()
129	            .expect("an absent observation mints an absent proof"),
130	    }
131	}
132	
133	fn registry_operation<'a>(request: &ProviderRequest<'a>) -> Result<&'a RegistryPublishOperation, GraphError> {
134	    match request.operation {
135	        PreparedOperation::RegistryPublish(operation) => Ok(operation),
136	        _ => Err(wrong_role(request.id, "registry publish")),
137	    }
138	}
139	
140	/// The one registry observation used by preflight, recovery, and post-publish
141	/// confirmation, so those three can never disagree.
142	fn registry_observation(
143	    adapter: &'static dyn RegistryEcosystem,
144	    context: &ProviderContext<'_>,
145	    operation: &RegistryPublishOperation,
146	) -> Result<ProviderObservationV1, GraphError> {
147	    if !adapter.can_observe_versions() {
148	        return Ok(ProviderObservationV1::Indeterminate {
149	            cause: ProviderIndeterminateCause::UnsupportedProvider,
150	        });
151	    }
152	    policy::retry_observation(context.sleeper(), || adapter.observe_once(context, operation))
153	}
154	
155	/// The same observation, but an absence is treated as index-propagation lag
156	/// rather than an answer: this only runs after a publish client reported the
157	/// version as newly published.
158	fn confirmed_registry_observation(
159	    adapter: &'static dyn RegistryEcosystem,
160	    context: &ProviderContext<'_>,
161	    operation: &RegistryPublishOperation,
162	) -> Result<ProviderObservationV1, GraphError> {
163	    policy::retry_observation(context.sleeper(), || {
164	        Ok(match adapter.observe_once(context, operation)? {
165	            Attempt::Settled(ProviderObservationV1::Absent) => Attempt::Transient {
166	                value: ProviderObservationV1::Absent,
167	                retry_after: None,
168	            },
169	            settled_or_transient => settled_or_transient,
170	        })
171	    })
172	}
173	
174	/// One ecosystem's registry client. This is the single place the release path
175	/// branches on [`Ecosystem`]: adding a registry means adding an adapter here,
176	/// not another match in preflight, dispatch, or confirmation.
177	pub(crate) trait RegistryEcosystem {
178	    /// Whether this registry exposes a query that proves an exact published
179	    /// version. `false` makes every observation `Indeterminate`, so a publish
180	    /// is never confirmed here and instead fails closed at the mandatory
181	    /// post-effect exact observation.
182	    fn can_observe_versions(&self) -> bool;
183	
184	    /// One observation attempt. Only called when [`Self::can_observe_versions`].
185	    fn observe_once(
186	        &self,
187	        context: &ProviderContext<'_>,
188	        operation: &RegistryPublishOperation,
189	    ) -> Result<Attempt<ProviderObservationV1>, GraphError>;
190	
191	    /// Runs the publish client and returns the output that decides the outcome.
192	    fn publish(
193	        &self,
194	        context: &ProviderContext<'_>,
195	        operation: &RegistryPublishOperation,
196	    ) -> Result<CommandOutput, GraphError>;
197	
198	    fn classify(&self, output: &CommandOutput) -> Result<PublishOutcome, RegistryError>;
199	}
200	
201	/// The production adapter set, keyed by ecosystem.
202	pub(crate) fn adapter_for(ecosystem: Ecosystem) -> Result<&'static dyn RegistryEcosystem, GraphError> {
203	    match ecosystem {
204	        Ecosystem::Cargo => Ok(&CargoRegistry),
205	        Ecosystem::Npm => Ok(&NpmRegistry),
206	        Ecosystem::Pypi => Ok(&PypiRegistry),
207	        _ => Err(GraphError::UnsupportedRelease {
208	            feature: UnsupportedReleaseFeature::Ecosystem,
209	        }),
210	    }
211	}
212	
213	/// Runs an [`registry_argv::Argv`] built by the pure argv layer. This is the
214	/// only place an adapter touches [`callisto_model::CommandRunner`] --
215	/// everything about *what* to run was already decided by `registry_argv`.
216	fn run_argv(context: &ProviderContext<'_>, argv: &registry_argv::Argv) -> Result<CommandOutput, GraphError> {
217	    let args: Vec<&str> = argv.args.iter().map(String::as_str).collect();
218	    Ok(context
219	        .runner()
220	        .run_with_timeout(&argv.program, &args, &argv.cwd, timeouts::PUBLISH)?)
221	}
222	
223	fn transient(
224	    cause: ProviderIndeterminateCause,
225	    retry_after: Option<std::time::Duration>,
226	) -> Attempt<ProviderObservationV1> {
227	    Attempt::Transient {
228	        value: ProviderObservationV1::Indeterminate { cause },
229	        retry_after,
230	    }
231	}
232	
233	fn settled(observation: ProviderObservationV1) -> Attempt<ProviderObservationV1> {
234	    Attempt::Settled(observation)
235	}
236	
237	struct CargoRegistry;
238	
239	/// The name the *cargo* client knows this registry by. Callisto's logical
240	/// `cratesIo` key is cargo's built-in `crates-io`; every other key is spelled
241	/// the same in `.cargo/config.toml` as it is in `callisto.toml`.
242	pub(crate) fn cargo_registry_name(key: &RegistryKey) -> &str {
243	    if key.as_str() == RegistryKey::CRATES_IO {
244	        "crates-io"
245	    } else {
246	        key.as_str()
247	    }
248	}
249	
250	/// The observation argv: `cargo info NAME@VERSION --registry REGISTRY`.
251	///
252	/// `--registry` is never omitted. Without it `cargo info` resolves the local
253	/// workspace and reports an unpublished member's on-disk version as published
254	/// (`version: X (from ./)`), which is the defect this observation exists to
255	/// avoid; with it, cargo reads only the named registry.
256	fn cargo_info_args<'a>(spec: &'a str, registry: &'a str) -> [&'a str; 4] {
257	    ["info", spec, "--registry", registry]
258	}
259	
260	impl RegistryEcosystem for CargoRegistry {
261	    fn can_observe_versions(&self) -> bool {
262	        true
263	    }
264	
265	    /// Runs from the source workspace root, so the same `.cargo/config.toml`
266	    /// registry definitions and credentials the publish effect uses apply --
267	    /// private registries and their auth are cargo's business, not ours.
268	    fn observe_once(
269	        &self,
270	        context: &ProviderContext<'_>,
271	        operation: &RegistryPublishOperation,
272	    ) -> Result<Attempt<ProviderObservationV1>, GraphError> {
273	        let spec = format!("{}@{}", operation.package_name, operation.version.render());
274	        let registry = cargo_registry_name(&operation.registry.key);
275	        let args = cargo_info_args(&spec, registry);
276	        let output = context
277	            .runner()
278	            .run_quiet(programs::CARGO, &args, context.root(), timeouts::REGISTRY_QUERY)?;
279	        Ok(classify_cargo_info(&output, &spec, &operation.version))
280	    }
281	
282	    fn publish(
283	        &self,
284	        context: &ProviderContext<'_>,
285	        operation: &RegistryPublishOperation,
286	    ) -> Result<CommandOutput, GraphError> {
287	        let registry_key =
288	            (operation.registry.key.as_str() != RegistryKey::CRATES_IO).then(|| operation.registry.key.as_str());
289	        let argv = registry_argv::cargo_publish_argv(
290	            context.root(),
291	            &operation.package_dir,
292	            &operation.package_name,
293	            &operation.version,
294	            registry_key,
295	        )?;
296	        run_argv(context, &argv)
297	    }
298	
299	    fn classify(&self, output: &CommandOutput) -> Result<PublishOutcome, RegistryError> {
300	        registry_argv::classify_cargo_output(output)
301	    }
302	}
303	
304	/// Classifies one real `cargo info` run. There is no `--json`, so the two
305	/// answers cargo actually proves are read from its exit code and its text:
306	///
307	/// - exit 0 with a `version: VERSION` line for the requested version: `Exact`.
308	///   `cargo info` reports neither the index checksum nor the yank flag, so the
309	///   evidence says `None` for both rather than inventing them.
310	/// - exit 101 with ``could not find `NAME@VERSION` ``: `Absent`.
311	/// - anything else -- another exit code, another message (a network failure
312	///   prints ``failed to load source for dependency``), or a zero exit with no
313	///   matching version line: transient `Indeterminate`, retried by the bounded
314	///   policy. An unreachable registry must never read as an absence.
315	///
316	/// A *yanked* version reads as `Absent`, because `cargo info` cannot see yanks
317	/// and answers "could not find" for one. That fails closed rather than open:
318	/// the publish attempt that follows is refused by the registry, and since only
319	/// an `Exact` observation may satisfy an operation, the run ends in the typed
320	/// `RegistryPublishUnconfirmed` error instead of a receipt.
321	fn classify_cargo_info(output: &CommandOutput, spec: &str, version: &Version) -> Attempt<ProviderObservationV1> {
322	    if output.success() {
323	        return if reports_version(&output.stdout, version) {
324	            settled(ProviderObservationV1::Exact {
325	                evidence: ProviderEvidenceV1::RegistryVersion {
326	                    version: version.clone(),
327	                    checksum: None,
328	                    yanked: None,
329	                },
330	            })
331	        } else {
332	            transient(ProviderIndeterminateCause::MalformedResponse, None)
333	        };
334	    }
335	    if output.exit_code == Some(101) && output.stderr.contains(&format!("could not find `{spec}`")) {
336	        return settled(ProviderObservationV1::Absent);
337	    }
338	    transient(ProviderIndeterminateCause::CommandFailed, None)
339	}
340	
341	/// Whether cargo's `version: X ...` line names exactly the requested version.
342	fn reports_version(stdout: &str, version: &Version) -> bool {
343	    stdout.lines().any(|line| {
344	        line.trim()
345	            .strip_prefix("version: ")
346	            .and_then(|rest| rest.strip_prefix(version.render()))
347	            .is_some_and(|rest| rest.is_empty() || rest.starts_with(char::is_whitespace))
348	    })
349	}
350	
351	struct NpmRegistry;
352	
353	impl RegistryEcosystem for NpmRegistry {
354	    fn can_observe_versions(&self) -> bool {
355	        true
356	    }
357	
358	    /// `npm view` keeps the workspace cwd: unlike a manifest-resolving client
359	    /// it never reads the local package, and the cwd is only where the project
360	    /// `.npmrc` supplying the registry is read from.
361	    fn observe_once(
362	        &self,
363	        context: &ProviderContext<'_>,
364	        operation: &RegistryPublishOperation,
365	    ) -> Result<Attempt<ProviderObservationV1>, GraphError> {
366	        let spec = format!("{}@{}", operation.package_name, operation.version.render());
367	        let mut args = vec!["view", spec.as_str(), "--json"];
368	        if let Some(registry) = operation.registry.endpoint.as_deref() {
369	            args.extend(["--registry", registry]);
370	        }
371	        let output = context
372	            .runner()
373	            .run_quiet(programs::NPM, &args, context.root(), timeouts::REGISTRY_QUERY)?;
374	        if output.success() {
375	            return Ok(if output.stdout_trimmed().is_empty() {
376	                settled(ProviderObservationV1::Absent)
377	            } else {
378	                // `npm view` reports no package checksum, so the evidence says
379	                // so rather than inventing one.
380	                settled(ProviderObservationV1::Exact {
381	                    evidence: ProviderEvidenceV1::RegistryVersion {
382	                        version: operation.version.clone(),
383	                        checksum: None,
384	                        yanked: None,
385	                    },
386	                })
387	            });
388	        }
389	        let details = format!("{}\n{}", output.stdout, output.stderr).to_ascii_lowercase();
390	        if details.contains("e404")
391	            || details.contains("etarget")
392	            || details.contains("no matching version")
393	            || details.contains("is not in this registry")
394	        {
395	            return Ok(settled(ProviderObservationV1::Absent));
396	        }
397	        Ok(transient(ProviderIndeterminateCause::CommandFailed, None))
398	    }
399	
400	    fn publish(
401	        &self,
402	        context: &ProviderContext<'_>,
403	        operation: &RegistryPublishOperation,
404	    ) -> Result<CommandOutput, GraphError> {
405	        let package_manager = registry_argv::detect_npm_package_manager(context.root());
406	        let argv = registry_argv::npm_publish_argv(
407	            context.root(),
408	            &operation.package_dir,
409	            &operation.package_name,
410	            package_manager,
411	            operation.npm_tag.as_deref(),
412	            operation.npm_access,
413	            operation.registry.endpoint.as_deref(),
414	        );
415	        run_argv(context, &argv)
416	    }
417	
418	    fn classify(&self, output: &CommandOutput) -> Result<PublishOutcome, RegistryError> {
419	        registry_argv::classify_npm_publish_output(output)
420	    }
421	}
422	
423	struct PypiRegistry;
424	
425	impl RegistryEcosystem for PypiRegistry {
426	    /// pip cannot prove a PyPI version absent: an unreachable index and a
427	    /// project that does not exist produce the same message and the same exit
428	    /// code, `pip index versions` is experimental and hides yanked releases,
429	    /// and a pinned yanked release installs with only a warning. Declaring the
430	    /// truth here is what makes [`require_observable_registry`] refuse a PyPI
431	    /// publish at plan time rather than letting one reach a receipt it cannot
432	    /// support.
433	    fn can_observe_versions(&self) -> bool {
434	        false
435	    }
436	
437	    fn observe_once(
438	        &self,
439	        _context: &ProviderContext<'_>,
440	        _operation: &RegistryPublishOperation,
441	    ) -> Result<Attempt<ProviderObservationV1>, GraphError> {
442	        Ok(settled(ProviderObservationV1::Indeterminate {
443	            cause: ProviderIndeterminateCause::UnsupportedProvider,
444	        }))
445	    }
446	
447	    fn publish(
448	        &self,
449	        context: &ProviderContext<'_>,
450	        operation: &RegistryPublishOperation,
451	    ) -> Result<CommandOutput, GraphError> {
452	        let steps = registry_argv::pypi_publish_argv(
453	            context.root(),
454	            &operation.package_dir,
455	            &operation.package_name,
456	            &operation.version,
457	            operation.registry.endpoint.as_deref(),
458	        );
459	        let [build, upload] = steps.as_slice() else {
460	            return Err(GraphError::ReleaseInvariant {
461	                detail: "pypi_publish_argv did not return exactly a build and an upload step".to_string(),
462	            });
463	        };
464	        let built = run_argv(context, build)?;
465	        if built.exit_code != Some(0) {
466	            return Err(GraphError::ReleaseCommand {
467	                program: build.program.clone(),
468	                args: build.args.clone(),
469	                failure: CommandFailure::NonZeroExit {
470	                    exit_code: built.exit_code,
471	                    stderr: built.stderr,
472	                },
473	            });
474	        }
475	        run_argv(context, upload)
476	    }
477	
478	    fn classify(&self, output: &CommandOutput) -> Result<PublishOutcome, RegistryError> {
479	        registry_argv::classify_twine_output(output)
480	    }
481	}
482	
483	/// The plan-time gate: an ecosystem whose client cannot prove a version absent
484	/// could never mint the absence proof an effect needs, nor the exact evidence a
485	/// receipt needs, so the plan is refused here rather than at dispatch.
486	pub(crate) fn require_observable_registry(ecosystem: Ecosystem) -> Result<(), GraphError> {
487	    if !adapter_for(ecosystem)?.can_observe_versions() {
488	        return Err(GraphError::ReleasePreconditionUnmet {
489	            requirement: ReleasePreconditionRequirement::ObservableRegistryClient,
490	        });
491	    }
492	    Ok(())
493	}
494	
