83	/// only: an effect (publish, push, release create, asset upload) is never
84	/// re-issued from here, because a transient error cannot prove the first
85	/// attempt did not take effect.
86	pub(crate) fn retry_observation<T>(
87	    sleeper: &dyn Sleeper,
88	    mut attempt: impl FnMut() -> Result<Attempt<T>, GraphError>,
89	) -> Result<T, GraphError> {
90	    let mut exhausted = None;
91	    for index in 0..OBSERVATION_MAX_ATTEMPTS {
92	        match attempt()? {
93	            Attempt::Settled(value) => return Ok(value),
94	            Attempt::Transient { value, retry_after } => {
95	                exhausted = Some(value);
96	                if index + 1 < OBSERVATION_MAX_ATTEMPTS {
97	                    sleeper.sleep(
98	                        retry_after
99	                            .unwrap_or_else(|| observation_backoff(index))
100	                            .min(OBSERVATION_BACKOFF_CAP),
101	                    );
102	                }
103	            }
104	        }
