1	//! The two forge roles: one draft GitHub release per prepared tag, and the
2	//! publication that closes it once every asset has been uploaded.
3	
4	use callisto_model::{
5	    ExactEvidence, ProviderConflictReason, ProviderEvidenceV1, ProviderIndeterminateCause, ProviderObservationV1,
6	    TagName,
7	};
8	
9	use crate::error::{CommandFailure, RemoteConflict};
10	use crate::GraphError;
11	
12	use super::super::github::{github_release_for_tag, GitHubReleaseLookup};
13	use super::policy::{programs, timeouts};
14	use super::{
15	    confirmed_evidence, wrong_role, EffectAuthorization, ForgePublishOperation, ForgeReleaseOperation,
16	    PreparedOperation, ProviderCapabilities, ProviderContext, ProviderRequest, ReleaseProvider,
17	};
18	
19	pub(crate) struct ForgeReleaseProvider;
20	
21	impl ReleaseProvider for ForgeReleaseProvider {
22	    fn capabilities(&self) -> ProviderCapabilities {
23	        ProviderCapabilities {
24	            can_observe: true,
25	            can_publish: true,
26	        }
27	    }
28	
29	    fn preflight_conflict(&self) -> RemoteConflict {
30	        RemoteConflict::ForgeReleaseDiffers
31	    }
32	
33	    fn observe(
34	        &self,
35	        context: &ProviderContext<'_>,
36	        request: &ProviderRequest<'_>,
37	    ) -> Result<ProviderObservationV1, GraphError> {
38	        let operation = forge_operation(request)?;
39	        let repository = context.github_repository_slug()?;
40	        observed_forge_release(
41	            context,
42	            &operation.tag,
43	            operation.prerelease,
44	            &repository,
45	            Draft::Either,
46	        )
47	    }
48	
49	    fn publish(
50	        &self,
51	        context: &ProviderContext<'_>,
52	        request: &ProviderRequest<'_>,
53	        _effect: &EffectAuthorization<'_>,
54	    ) -> Result<ExactEvidence, GraphError> {
55	        let operation = forge_operation(request)?;
56	        let repository = context.github_repository_slug()?;
57	        let mut create_args = vec![
58	            "release",
59	            "create",
60	            operation.tag.as_str(),
61	            "--repo",
62	            repository.as_str(),
63	            "--verify-tag",
64	            "--draft",
65	            "--generate-notes",
66	        ];
67	        if operation.prerelease {
68	            create_args.push("--prerelease");
69	        }
70	        run_gh(context, &create_args, timeouts::FORGE_RELEASE_CREATE)?;
71	        confirmed_evidence(
72	            observed_forge_release(
73	                context,
74	                &operation.tag,
75	                operation.prerelease,
76	                &repository,
77	                Draft::Either,
78	            )?,
79	            request.id,
80	            RemoteConflict::ForgeReleaseNotObservedAfterCreate,
81	        )
82	    }
83	}
84	
85	pub(crate) struct ForgePublishProvider;
86	
87	impl ReleaseProvider for ForgePublishProvider {
88	    fn capabilities(&self) -> ProviderCapabilities {
89	        ProviderCapabilities {
90	            can_observe: true,
91	            can_publish: true,
92	        }
93	    }
94	
95	    fn preflight_conflict(&self) -> RemoteConflict {
96	        RemoteConflict::ForgeReleaseDiffers
97	    }
98	
99	    fn observe(
100	        &self,
101	        context: &ProviderContext<'_>,
102	        request: &ProviderRequest<'_>,
103	    ) -> Result<ProviderObservationV1, GraphError> {
104	        let operation = publish_operation(request)?;
105	        let repository = context.github_repository_slug()?;
106	        observed_forge_release(
107	            context,
108	            &operation.tag,
109	            operation.prerelease,
110	            &repository,
111	            Draft::PublishedOnly,
112	        )
113	    }
114	
115	    fn publish(
116	        &self,
117	        context: &ProviderContext<'_>,
118	        request: &ProviderRequest<'_>,
119	        _effect: &EffectAuthorization<'_>,
120	    ) -> Result<ExactEvidence, GraphError> {
121	        let operation = publish_operation(request)?;
122	        let repository = context.github_repository_slug()?;
123	        run_gh(
124	            context,
125	            &[
126	                "release",
127	                "edit",
128	                operation.tag.as_str(),
129	                "--repo",
130	                repository.as_str(),
131	                "--draft=false",
132	            ],
133	            timeouts::FORGE_RELEASE_CREATE,
134	        )?;
135	        confirmed_evidence(
136	            observed_forge_release(
137	                context,
138	                &operation.tag,
139	                operation.prerelease,
140	                &repository,
141	                Draft::PublishedOnly,
142	            )?,
143	            request.id,
144	            RemoteConflict::ForgeReleaseNotObservedAfterPublish,
145	        )
146	    }
147	}
148	
149	/// Whether a still-draft release satisfies the observing role.
150	#[derive(Clone, Copy, PartialEq, Eq)]
151	enum Draft {
152	    Either,
153	    PublishedOnly,
154	}
155	
156	fn run_gh(context: &ProviderContext<'_>, args: &[&str], timeout: std::time::Duration) -> Result<(), GraphError> {
157	    let output = context
158	        .runner()
159	        .run_with_timeout(programs::GH, args, context.root(), timeout)?;
160	    if output.success() {
161	        return Ok(());
162	    }
163	    Err(GraphError::ReleaseCommand {
164	        program: programs::GH.to_owned(),
165	        args: args.iter().map(ToString::to_string).collect(),
166	        failure: CommandFailure::NonZeroExit {
167	            exit_code: output.exit_code,
168	            stderr: output.stderr,
169	        },
170	    })
171	}
172	
173	fn forge_operation<'a>(request: &ProviderRequest<'a>) -> Result<&'a ForgeReleaseOperation, GraphError> {
174	    match request.operation {
175	        PreparedOperation::ForgeRelease(operation) => Ok(operation),
176	        _ => Err(wrong_role(request.id, "forge release")),
177	    }
178	}
179	
180	fn publish_operation<'a>(request: &ProviderRequest<'a>) -> Result<&'a ForgePublishOperation, GraphError> {
181	    match request.operation {
182	        PreparedOperation::ForgePublish(operation) => Ok(operation),
183	        _ => Err(wrong_role(request.id, "forge publish")),
184	    }
185	}
186	
187	/// A release created for an existing tag reports the repository's default
188	/// branch as `target_commitish`, so that field proves nothing about the
189	/// released commit. The tag operation is a DAG prerequisite of the forge
190	/// release, so the tag already binds this release's name to its commit.
191	fn observed_forge_release(
192	    context: &ProviderContext<'_>,
193	    tag: &TagName,
194	    prerelease: bool,
195	    repository: &str,
196	    draft_policy: Draft,
197	) -> Result<ProviderObservationV1, GraphError> {
198	    let value = match github_release_for_tag(context.root(), context.runner(), context.sleeper(), repository, tag)? {
199	        GitHubReleaseLookup::Absent => return Ok(ProviderObservationV1::Absent),
200	        GitHubReleaseLookup::Indeterminate { status } => {
201	            return Ok(ProviderObservationV1::Indeterminate {
202	                cause: ProviderIndeterminateCause::ProviderStatus { status },
203	            })
204	        }
205	        GitHubReleaseLookup::Found(value) => value,
206	    };
207	    if value.get("tag_name").and_then(serde_json::Value::as_str) != Some(tag.as_str()) {
208	        return Ok(ProviderObservationV1::Conflict {
209	            reason: ProviderConflictReason::ForgeReleaseDiffers,
210	        });
211	    }
212	    if value
213	        .get("prerelease")
214	        .and_then(serde_json::Value::as_bool)
215	        .unwrap_or(false)
216	        != prerelease
217	    {
218	        return Ok(ProviderObservationV1::Conflict {
219	            reason: ProviderConflictReason::ForgeReleasePrereleaseDiffers,
220	        });
221	    }
222	    let draft = value.get("draft").and_then(serde_json::Value::as_bool).unwrap_or(false);
223	    if draft && draft_policy == Draft::PublishedOnly {
224	        return Ok(ProviderObservationV1::Absent);
225	    }
226	    Ok(ProviderObservationV1::Exact {
227	        evidence: ProviderEvidenceV1::ForgeRelease {
228	            tag_name: tag.clone(),
229	            draft,
230	        },
231	    })
232	}
233	
234	/// The existence check every artifact upload makes against the draft it
235	/// attaches to; the upload role owns no forge-release identity of its own.
236	pub(crate) fn observed_draft_or_published_release(
237	    context: &ProviderContext<'_>,
238	    tag: &TagName,
239	    prerelease: bool,
240	    repository: &str,
241	) -> Result<ProviderObservationV1, GraphError> {
242	    observed_forge_release(context, tag, prerelease, repository, Draft::Either)
243	}
