463	        let tag = listed[1]["tag_name"].as_str().unwrap().to_owned();
464	        let runner = ScriptedGh {
465	            tag_endpoint: None,
466	            pages: vec![fixtures::GITHUB_RELEASE_LIST.to_owned()],
467	        };
468	        assert!(matches!(
469	            observe_tag(&runner, &tag, false, Draft::Either),
470	            ProviderObservationV1::Exact { .. }
471	        ));
472	        assert!(matches!(
473	            observe_tag(&runner, "callisto-no-such-tag", false, Draft::Either),
474	            ProviderObservationV1::Absent
475	        ));
476	    }
477	}
