1	//! The GitHub Releases read path: argv, HTTP framing, and response parsing.
2	//!
3	//! Kept free of any provider so the forge-release and artifact-upload roles
4	//! share one lookup and cannot drift in how they read an absence.
5	
6	use std::path::Path;
7	
8	use callisto_model::{CommandOutput, CommandRunner, TagName};
9	
10	use crate::error::CommandFailure;
11	use crate::GraphError;
12	
13	use super::provider::http::{parse_http_response, HttpResponse};
14	use super::provider::policy::{programs, retry_observation, timeouts, Attempt, Sleeper};
15	
16	/// One GitHub release lookup, shared by the forge-release and asset adapters.
17	#[derive(Debug)]
18	pub(crate) enum GitHubReleaseLookup {
19	    Absent,
20	    Indeterminate { status: u16 },
21	    Found(serde_json::Value),
22	}
23	
24	pub(crate) fn github_release_endpoint(repository: &str, tag: &TagName) -> String {
25	    format!("repos/{repository}/releases/tags/{tag}")
26	}
27	
28	/// GitHub serves at most 100 releases per page; ten pages is the bound this
29	/// scan will spend looking for one draft before reporting it unobservable.
30	const RELEASE_LIST_PAGE_SIZE: usize = 100;
31	const RELEASE_LIST_PAGE_LIMIT: usize = 10;
32	
33	fn github_release_list_endpoint(repository: &str, page: usize) -> String {
34	    format!("repos/{repository}/releases?per_page={RELEASE_LIST_PAGE_SIZE}&page={page}")
35	}
36	
37	/// `gh api` defines no `--repo`; the endpoint already carries owner and repository.
38	pub(crate) fn github_release_api_args(endpoint: &str) -> [&str; 5] {
39	    ["api", "--include", "--method", "GET", endpoint]
40	}
41	
42	fn parse_github_api_response(program: &str, args: &[&str], stdout: &str) -> Result<HttpResponse, GraphError> {
43	    parse_http_response(stdout).map_err(|detail| GraphError::ReleaseCommand {
44	        program: program.to_string(),
45	        args: args.iter().map(ToString::to_string).collect(),
46	        failure: CommandFailure::MalformedOutput { detail },
47	    })
48	}
49	
50	/// `gh api --include` preserves the HTTP response even for a 404 and exits
51	/// non-zero. Parse that authoritative response first so absence is not
52	/// mistaken for a transport failure; retain the command failure when no
53	/// parseable HTTP response was produced.
54	fn github_api_response(program: &str, args: &[&str], output: &CommandOutput) -> Result<HttpResponse, GraphError> {
55	    match parse_github_api_response(program, args, &output.stdout) {
56	        Ok(response) => Ok(response),
57	        Err(_) if !output.success() => Err(GraphError::ReleaseCommand {
58	            program: program.to_owned(),
59	            args: args.iter().map(ToString::to_string).collect(),
60	            failure: CommandFailure::NonZeroExit {
61	                exit_code: output.exit_code,
62	                stderr: output.stderr.clone(),
63	            },
64	        }),
65	        Err(error) => Err(error),
66	    }
67	}
68	
69	/// Classifies an HTTP response before parsing a GitHub Release body. A 404
70	/// proves absence; all other non-success statuses leave remote identity
71	/// unknown. In particular, authentication, rate-limit, and server failures
72	/// must never be reported as a conflicting release or asset.
73	fn github_release_response_status(status: u16) -> Option<GitHubReleaseLookup> {
74	    match status {
75	        200 => None,
76	        404 => Some(GitHubReleaseLookup::Absent),
77	        other => Some(GitHubReleaseLookup::Indeterminate { status: other }),
78	    }
79	}
80	
81	/// The one GET every forge observation shares, under the same bounded retry as
82	/// every other read-only observation.
83	///
84	/// This endpoint never serves drafts, so it proves publication, not existence;
85	/// [`github_release_for_tag`] is what the roles call.
86	fn github_release_by_tag(
87	    root: &Path,
88	    runner: &dyn CommandRunner,
89	    sleeper: &dyn Sleeper,
90	    repository: &str,
91	    tag: &TagName,
92	) -> Result<GitHubReleaseLookup, GraphError> {
93	    let endpoint = github_release_endpoint(repository, tag);
94	    retry_observation(sleeper, || github_api_get_once(root, runner, &endpoint))
95	}
96	
97	/// Finds the release for `tag` whether it is published or still a draft.
98	///
99	/// `GET /releases/tags/{tag}` omits drafts entirely, so a 404 there is not
100	/// absence: the bounded list scan below is the only way to observe a draft.
101	pub(crate) fn github_release_for_tag(
102	    root: &Path,
103	    runner: &dyn CommandRunner,
104	    sleeper: &dyn Sleeper,
105	    repository: &str,
106	    tag: &TagName,
107	) -> Result<GitHubReleaseLookup, GraphError> {
108	    match github_release_by_tag(root, runner, sleeper, repository, tag)? {
109	        GitHubReleaseLookup::Absent => {}
110	        found_or_unknown => return Ok(found_or_unknown),
111	    }
112	    for page in 1..=RELEASE_LIST_PAGE_LIMIT {
113	        let endpoint = github_release_list_endpoint(repository, page);
114	        let listed = match retry_observation(sleeper, || github_api_get_once(root, runner, &endpoint))? {
115	            GitHubReleaseLookup::Found(listed) => listed,
116	            absent_or_unknown => return Ok(absent_or_unknown),
117	        };
118	        let releases = listed
119	            .as_array()
120	            .ok_or_else(|| malformed_github_response(&endpoint, "GitHub release list response is not an array"))?;
121	        if releases.is_empty() {
122	            break;
123	        }
124	        if let Some(release) = releases
125	            .iter()
126	            .find(|release| release.get("tag_name").and_then(serde_json::Value::as_str) == Some(tag.as_str()))
127	        {
128	            return Ok(GitHubReleaseLookup::Found(release.clone()));
129	        }
130	    }
131	    Ok(GitHubReleaseLookup::Absent)
132	}
133	
134	pub(crate) fn malformed_github_response(endpoint: &str, detail: &str) -> GraphError {
135	    GraphError::ReleaseCommand {
136	        program: programs::GH.to_owned(),
137	        args: github_release_api_args(endpoint)
138	            .iter()
139	            .map(ToString::to_string)
140	            .collect(),
141	        failure: CommandFailure::MalformedOutput {
142	            detail: detail.to_owned(),
143	        },
144	    }
145	}
146	
147	fn github_api_get_once(
148	    root: &Path,
149	    runner: &dyn CommandRunner,
150	    endpoint: &str,
151	) -> Result<Attempt<GitHubReleaseLookup>, GraphError> {
152	    let api_args = github_release_api_args(endpoint);
153	    let observed = runner.run_with_timeout(programs::GH, &api_args, root, timeouts::FORGE_API)?;
154	    let response = github_api_response(programs::GH, &api_args, &observed)?;
155	    if let Some(lookup) = github_release_response_status(response.status) {
156	        return Ok(
157	            if matches!(response.status, 429 | 500..=599) || (response.status == 403 && response.is_rate_limited()) {
158	                Attempt::Transient {
159	                    value: lookup,
160	                    retry_after: response.retry_after(),
161	                }
162	            } else {
163	                Attempt::Settled(lookup)
164	            },
165	        );
166	    }
167	    let value: serde_json::Value =
168	        serde_json::from_str(&response.body).map_err(|error| GraphError::ReleaseCommand {
169	            program: programs::GH.to_string(),
170	            args: api_args.iter().map(ToString::to_string).collect(),
171	            failure: CommandFailure::MalformedOutput {
172	                detail: error.to_string(),
173	            },
174	        })?;
175	    Ok(Attempt::Settled(GitHubReleaseLookup::Found(value)))
176	}
177	
178	#[cfg(test)]
179	mod tests {
180	    use super::*;
181	
182	    #[test]
183	    fn github_api_observation_parser_requires_an_explicit_http_status() {
184	        let response = parse_github_api_response(
185	            "gh",
186	            &["api"],
187	            "HTTP/2 404\r\ncontent-type: application/json\r\n\r\n{\"message\":\"Not Found\"}",
188	        )
189	        .unwrap();
190	        assert_eq!(response.status, 404);
191	        assert_eq!(response.body, "{\"message\":\"Not Found\"}");
192	        assert!(parse_github_api_response("gh", &["api"], "not a response").is_err());
193	    }
194	
195	    #[test]
196	    fn github_api_response_preserves_a_parseable_not_found_on_nonzero_exit() {
197	        let output = CommandOutput {
198	            exit_code: Some(1),
199	            stdout: "HTTP/2 404\r\ncontent-type: application/json\r\n\r\n{\"message\":\"Not Found\"}".to_owned(),
