29	/// tests run against. Shared verbatim with the CLI end-to-end harness so both
30	/// are held to the same captured bytes.
31	#[cfg(test)]
32	#[path = "../../../../../../testing/loopback_http.rs"]
33	pub(crate) mod loopback;
34	
35	/// The invocation data for one effect. This is deliberately graph-private:
36	/// callers can inspect the serializable intent, but cannot substitute a new
37	/// endpoint, tag target, or package directory at execution time.
38	#[derive(Debug)]
39	pub(crate) enum PreparedOperation {
40	    RegistryPublish(RegistryPublishOperation),
41	    Tag(TagOperation),
42	    ForgeRelease(ForgeReleaseOperation),
43	    ArtifactUpload(ArtifactUploadOperation),
44	    ForgePublish(ForgePublishOperation),
45	}
46	
47	#[derive(Debug)]
48	pub(crate) struct RegistryPublishOperation {
49	    pub(crate) package_dir: PathBuf,
50	    pub(crate) package_name: String,
51	    pub(crate) version: Version,
52	    pub(crate) registry: PreparedRegistryBinding,
53	    pub(crate) npm_access: Option<NpmAccess>,
54	    pub(crate) npm_tag: Option<String>,
55	}
56	
57	#[derive(Debug)]
58	pub(crate) struct TagOperation {
59	    pub(crate) name: TagName,
60	    pub(crate) target: CommitSha,
61	    pub(crate) annotation: String,
62	}
63	
64	#[derive(Debug)]
65	pub(crate) struct ForgeReleaseOperation {
66	    pub(crate) tag: TagName,
67	    pub(crate) prerelease: bool,
68	}
69	
70	#[derive(Debug)]
71	pub(crate) struct ArtifactUploadOperation {
72	    pub(crate) slot: ArtifactSlotId,
73	    pub(crate) tag: TagName,
74	    pub(crate) prerelease: bool,
75	}
76	
77	#[derive(Debug)]
78	pub(crate) struct ForgePublishOperation {
79	    pub(crate) tag: TagName,
80	    pub(crate) prerelease: bool,
81	}
82	
83	/// What one pre-effect observation authorizes for an operation, carrying the
84	/// proof token the state machine requires to act on it.
85	#[derive(Debug)]
86	pub enum ReleasePreflight {
87	    /// The effect has not happened and may be issued.
88	    Proceed { proof: AbsentProof },
89	    /// The provider already holds exactly this operation's intended result.
90	    AlreadySatisfied { evidence: ExactEvidence },
91	}
92	
93	/// The executor's whole view of the outside world.
94	///
95	/// Keeping it this small is deliberate: a test set holding nothing but a map
96	/// of canned observations satisfies it, which is what makes the executor's
97	/// crash and convergence paths testable without a provider on `PATH`.
98	pub trait ReleaseProviderSet {
99	    /// The immutable intent every operation id must belong to.
100	    fn intent(&self) -> &ReleaseIntentV1;
101	
102	    /// Re-observes the held workspace immediately before an effect.
103	    fn recheck_trust(&self) -> Result<(), GraphError>;
104	
105	    /// The single fresh pre-effect observation for one operation, made before
106	    /// the executor persists `Attempting` so a failure here cannot strand the
107	    /// operation mid-flight.
108	    fn preflight(
109	        &self,
110	        id: &ReleaseOperationId,
111	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
112	    ) -> Result<ReleasePreflight, GraphError>;
113	
114	    /// A fresh observation of what the provider holds, with no effect.
115	    fn observe(
116	        &self,
117	        id: &ReleaseOperationId,
118	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
119	    ) -> Result<ProviderObservationV1, GraphError>;
120	
121	    /// A fresh observation made after the effect was expected to land, used to
122	    /// build the terminal receipt. A registry index that has not propagated
123	    /// yet is retried rather than reported absent, under the same bounded
124	    /// policy the post-publish confirmation uses.
125	    ///
126	    /// It cannot make a receipt easier to obtain: every operation still needs
127	    /// a fresh `Exact`.
128	    fn observe_settled(
129	        &self,
130	        id: &ReleaseOperationId,
131	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
132	    ) -> Result<ProviderObservationV1, GraphError> {
133	        self.observe(id, artifacts)
134	    }
135	
136	    /// Issues the one mutating action for this operation and confirms it.
137	    /// `proof` is only obtainable from an `Absent` pre-effect observation.
138	    fn publish(
139	        &self,
140	        permit: &ApplyPermit,
141	        proof: &AbsentProof,
142	        id: &ReleaseOperationId,
143	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
144	    ) -> Result<ExactEvidence, GraphError>;
145	}
146	
147	/// What one provider role can do.
148	///
149	/// `can_observe` means the role answers an observation at all, not that the
150	/// answer can be exact: PyPI answers `Indeterminate` because its upload
151	/// endpoint is not a query API, and that is still an answer the executor can
152	/// fail closed on.
153	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
154	pub(crate) struct ProviderCapabilities {
155	    pub(crate) can_observe: bool,
156	    pub(crate) can_publish: bool,
157	}
158	
159	/// The permit and the absence proof that together authorize one effect.
160	pub(crate) struct EffectAuthorization<'a> {
161	    pub(crate) permit: &'a ApplyPermit,
162	    #[allow(dead_code)] // a type-level token: holding it is the authorization
163	    pub(crate) proof: &'a AbsentProof,
164	}
165	
166	/// One operation's whole provider-visible input.
167	pub(crate) struct ProviderRequest<'a> {
168	    pub(crate) id: &'a ReleaseOperationId,
169	    pub(crate) operation: &'a PreparedOperation,
170	    pub(crate) artifacts: Option<&'a VerifiedArtifactManifest<'a>>,
171	}
172	
173	/// Everything a provider may touch outside its prepared operation.
174	pub(crate) struct ProviderContext<'a> {
175	    root: &'a Path,
176	    runner: &'a dyn CommandRunner,
177	    git_remote: Option<&'a PreparedGitRemote>,
178	    sleeper: &'a dyn policy::Sleeper,
179	}
180	
181	impl<'a> ProviderContext<'a> {
182	    pub(crate) fn new(
183	        root: &'a Path,
184	        runner: &'a dyn CommandRunner,
185	        git_remote: Option<&'a PreparedGitRemote>,
186	    ) -> Self {
187	        ProviderContext {
188	            root,
189	            runner,
190	            git_remote,
191	            sleeper: &policy::ThreadSleeper,
192	        }
193	    }
194	
195	    /// Replaces the wall-clock wait, so a test can exercise the retry schedule
196	    /// without spending it.
197	    #[cfg(test)]
198	    pub(crate) fn with_sleeper(mut self, sleeper: &'a dyn policy::Sleeper) -> Self {
199	        self.sleeper = sleeper;
200	        self
201	    }
202	
203	    pub(crate) fn root(&self) -> &'a Path {
204	        self.root
205	    }
206	
207	    pub(crate) fn runner(&self) -> &'a dyn CommandRunner {
208	        self.runner
209	    }
210	
211	    pub(crate) fn sleeper(&self) -> &'a dyn policy::Sleeper {
212	        self.sleeper
213	    }
214	
215	    pub(crate) fn checked_git_remote(&self) -> Result<&'a PreparedGitRemote, GraphError> {
216	        let expected = self.git_remote.ok_or(GraphError::ReleasePreconditionUnmet {
217	            requirement: ReleasePreconditionRequirement::GitRemotePrepared,
218	        })?;
219	        recheck_git_remote(self.root, self.runner, expected)?;
220	        Ok(expected)
221	    }
222	
223	    /// The checked remote's `owner/repo` slug.
224	    pub(crate) fn github_repository_slug(&self) -> Result<String, GraphError> {
225	        Ok(self
226	            .checked_git_remote()?
227	            .github_repository
228	            .as_ref()
229	            .ok_or(GraphError::ReleasePreconditionUnmet {
230	                requirement: ReleasePreconditionRequirement::GitHubRemote,
231	            })?
232	            .as_slug())
233	    }
234	}
235	
236	/// One operation role's adapter: what it can do, what it sees, what it does.
237	pub(crate) trait ReleaseProvider {
238	    fn capabilities(&self) -> ProviderCapabilities;
239	
240	    fn observe(
241	        &self,
242	        context: &ProviderContext<'_>,
243	        request: &ProviderRequest<'_>,
244	    ) -> Result<ProviderObservationV1, GraphError>;
245	
246	    /// Issues the one mutating action, then re-observes: the returned evidence
247	    /// is always a post-effect observation, never the client's own exit code.
248	    fn publish(
249	        &self,
250	        context: &ProviderContext<'_>,
251	        request: &ProviderRequest<'_>,
252	        effect: &EffectAuthorization<'_>,
253	    ) -> Result<ExactEvidence, GraphError>;
254	
255	    /// The same observation, made when the effect is believed to have landed
256	    /// already, so a provider whose index propagates asynchronously may treat
257	    /// an absence as lag and retry instead of answering `Absent`.
258	    ///
259	    /// This never widens what counts as success -- only `Exact` ever is -- it
260	    /// only stops a lagging index being mistaken for a missing effect. Roles
261	    /// whose providers answer synchronously reuse [`Self::observe`].
262	    fn observe_settled(
263	        &self,
264	        context: &ProviderContext<'_>,
265	        request: &ProviderRequest<'_>,
266	    ) -> Result<ProviderObservationV1, GraphError> {
267	        self.observe(context, request)
268	    }
269	
270	    /// The disagreement this role reports when a pre-effect observation is
271	    /// neither absent nor exactly the intended result.
272	    fn preflight_conflict(&self) -> RemoteConflict;
273	
274	    fn preflight(
275	        &self,
276	        context: &ProviderContext<'_>,
277	        request: &ProviderRequest<'_>,
278	    ) -> Result<ReleasePreflight, GraphError> {
279	        preflight_from_observation(self.observe(context, request)?, request.id, self.preflight_conflict())
280	    }
281	}
282	
283	/// The one place a prepared operation is routed to the provider that performs
284	/// it. Roles are selected here; the registry role selects its per-ecosystem
285	/// adapter in [`registry::adapter_for`], which is the only other selection.
286	fn provider_for(operation: &PreparedOperation) -> &'static dyn ReleaseProvider {
287	    match operation {
288	        PreparedOperation::RegistryPublish(_) => &registry::RegistryProvider,
289	        PreparedOperation::Tag(_) => &tag::TagProvider,
290	        PreparedOperation::ForgeRelease(_) => &forge::ForgeReleaseProvider,
291	        PreparedOperation::ArtifactUpload(_) => &artifact::ArtifactUploadProvider,
292	        PreparedOperation::ForgePublish(_) => &forge::ForgePublishProvider,
293	    }
294	}
295	
296	/// A role that can issue an effect but cannot be asked what the provider holds
297	/// could never prove absence before acting, so it is refused here -- before any
298	/// observation or effect -- rather than at dispatch.
299	pub(crate) fn checked_provider_for(operation: &PreparedOperation) -> Result<&'static dyn ReleaseProvider, GraphError> {
300	    let provider = provider_for(operation);
301	    require_observable(provider.capabilities())?;
302	    Ok(provider)
303	}
304	
305	fn require_observable(capabilities: ProviderCapabilities) -> Result<(), GraphError> {
306	    if capabilities.can_publish && !capabilities.can_observe {
307	        return Err(GraphError::ReleasePreconditionUnmet {
308	            requirement: ReleasePreconditionRequirement::ObservableProvider,
309	        });
310	    }
311	    Ok(())
312	}
313	
314	/// Maps one observation to its pre-effect decision. `conflict` names the
315	/// operation-specific disagreement so the typed error stays precise.
316	pub(crate) fn preflight_from_observation(
317	    observation: ProviderObservationV1,
318	    id: &ReleaseOperationId,
319	    conflict: RemoteConflict,
320	) -> Result<ReleasePreflight, GraphError> {
321	    match &observation {
322	        ProviderObservationV1::Absent => Ok(ReleasePreflight::Proceed {
323	            proof: observation
324	                .absent_proof()
325	                .expect("an absent observation mints an absent proof"),
326	        }),
327	        ProviderObservationV1::Exact { .. } => Ok(ReleasePreflight::AlreadySatisfied {
328	            evidence: observation
329	                .exact_evidence()
330	                .expect("an exact observation mints its evidence"),
331	        }),
332	        ProviderObservationV1::Conflict { .. } => Err(GraphError::ReleaseRemoteConflict { conflict }),
333	        ProviderObservationV1::Indeterminate { .. } => Err(GraphError::ReleaseProviderIndeterminate {
334	            operation: Box::new(id.clone()),
335	        }),
336	    }
337	}
338	
339	/// Requires that a post-effect observation is exact before the operation may
340	/// be recorded as done.
341	pub(crate) fn confirmed_evidence(
342	    observation: ProviderObservationV1,
343	    id: &ReleaseOperationId,
344	    conflict: RemoteConflict,
345	) -> Result<ExactEvidence, GraphError> {
346	    match &observation {
347	        ProviderObservationV1::Exact { .. } => Ok(observation
348	            .exact_evidence()
349	            .expect("an exact observation mints its evidence")),
350	        ProviderObservationV1::Indeterminate { .. } => Err(GraphError::ReleaseProviderIndeterminate {
351	            operation: Box::new(id.clone()),
352	        }),
353	        ProviderObservationV1::Absent | ProviderObservationV1::Conflict { .. } => {
354	            Err(GraphError::ReleaseRemoteConflict { conflict })
355	        }
356	    }
357	}
358	
359	/// The invariant error a provider raises when it is handed another role's
360	/// prepared operation.
361	pub(crate) fn wrong_role(id: &ReleaseOperationId, expected: &str) -> GraphError {
362	    GraphError::ReleaseInvariant {
363	        detail: format!("operation `{id:?}` is not a prepared {expected} operation"),
364	    }
365	}
366	
367	#[cfg(test)]
368	mod tests {
369	    use super::*;
370	
371	    /// Every production role must be able to answer an observation, because
372	    /// the executor may only issue an effect against a proved absence.
373	    #[test]
374	    fn no_production_provider_can_publish_without_being_observable() {
375	        for provider in [
376	            &registry::RegistryProvider as &dyn ReleaseProvider,
377	            &tag::TagProvider,
378	            &forge::ForgeReleaseProvider,
379	            &artifact::ArtifactUploadProvider,
380	            &forge::ForgePublishProvider,
381	        ] {
382	            let capabilities = provider.capabilities();
383	            assert!(
384	                capabilities.can_observe,
385	                "a publishing provider that cannot observe would act without proof of absence"
386	            );
387	            assert!(capabilities.can_publish);
388	        }
389	    }
390	
391	    #[test]
392	    fn a_publish_only_role_is_refused_and_every_other_shape_is_allowed() {
393	        let error = require_observable(ProviderCapabilities {
394	            can_observe: false,
395	            can_publish: true,
396	        })
397	        .unwrap_err();
398	        assert!(
399	            matches!(
400	                error,
401	                GraphError::ReleasePreconditionUnmet {
402	                    requirement: ReleasePreconditionRequirement::ObservableProvider
403	                }
404	            ),
405	            "expected ReleasePreconditionUnmet(ObservableProvider), got {error:?}"
406	        );
407	        for capabilities in [
408	            ProviderCapabilities {
409	                can_observe: true,
410	                can_publish: true,
411	            },
412	            ProviderCapabilities {
413	                can_observe: true,
414	                can_publish: false,
415	            },
416	            ProviderCapabilities {
417	                can_observe: false,
418	                can_publish: false,
419	            },
420	        ] {
421	            assert!(
422	                require_observable(capabilities).is_ok(),
423	                "{capabilities:?} must be allowed"
424	            );
425	        }
426	    }
427	}
